tool_calls.arguments:
{"command":"kubectl patch pod app -n default --patch '
{
  "spec": {
    "containers": [
      {
        "name": "page-writer",
        "image": "busybox:1.37.0",
        "command": ["sh", "-c", "echo \"<h1>Hello from the Page Writer!</h1>\" > /srv/index.html"],
        "volumeMounts": [
          {
            "name": "shared",
            "mountPath": "/srv"
          }
        ]
      }
    ]
  }
}'
"}

